class Evaluator:
    def __init__(self, expression):
        self.expression = expression
        self.position = 0
        self.current_char = None
        self.next_char()

    def next_char(self):
        if self.position < len(self.expression):
            self.current_char = self.expression[self.position]
            self.position += 1
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.next_char()

    def parse_number(self):
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.next_char()
        return float(num_str) if num_str else 0

    def parse_term(self):
        result = self.parse_factor()
        while self.current_char in ('*', '/'):
            op = self.current_char
            self.next_char()
            if op == '*':
                result *= self.parse_factor()
            elif op == '/':
                denominator = self.parse_factor()
                if denominator == 0:
                    raise ZeroDivisionError("division by zero")
                result /= denominator
        return result

    def parse_factor(self):
        self.skip_whitespace()
        if self.current_char == '(':
            self.next_char()
            result = self.parse_expression()
            self.next_char()  # Skip closing parenthesis
            return result
        else:
            return self.parse_number()

    def parse_expression(self):
        result = self.parse_term()
        while self.current_char in ('+', '-'):
            op = self.current_char
            self.next_char()
            if op == '+':
                result += self.parse_term()
            elif op == '-':
                result -= self.parse_term()
        return result

def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression using a recursive descent parser."""
    evaluator = Evaluator(expr)
    return evaluator.parse_expression()

